import java.util.*;

public class WrapperDemo {
    public static void main(String[] args) {
        // Collections require objects, not primitives
        List<Integer> scores = new ArrayList<>();
        scores.add(95);  // autoboxing: int → Integer
        scores.add(Integer.valueOf(88));

        int firstScore = scores.get(0);  // unboxing: Integer → int

        // Parsing strings to primitives/wrappers
        String input = "42";
        int primitiveValue = Integer.parseInt(input);  // returns int
        Integer objectValue = Integer.valueOf(input);  // returns Integer

        // Using wrapper constants
        int maxInt = Integer.MAX_VALUE;  // 2,147,483,647
        boolean isLarge = primitiveValue > Integer.MAX_VALUE / 2;

        System.out.println("Scores: " + scores);
    }
}

import java.util.*;

public class IntegerBoundsDemo {
    public static void main(String[] args) {
        int[] scores = {45, 92, 67, 88, 23};

        // Finding maximum: initialize to MIN_VALUE
        int max = Integer.MIN_VALUE;
        for (int score : scores) {
            if (score > max) {
                max = score;
            }
        }
        System.out.println("Max score: " + max);

        // Demonstrating overflow behavior
        int atLimit = Integer.MAX_VALUE;
        System.out.println("MAX_VALUE: " + atLimit);
        System.out.println("MAX_VALUE + 1: " + (atLimit + 1));  // wraps to MIN_VALUE

        // Safe overflow detection before calculation
        int a = Integer.MAX_VALUE - 10;
        int b = 20;
        if (a > Integer.MAX_VALUE - b) {
            System.out.println("Addition would overflow, use long");
        }
    }
}

public class CharacterMethodsDemo {
    public static void main(String[] args) {
        String input = "User123 ";

        // Character-by-character validation
        for (char c : input.toCharArray()) {
            if (Character.isDigit(c)) {
                int digitValue = Character.getNumericValue(c);  // '1' → 1
                System.out.println(c + " is digit with value " + digitValue);
            } else if (Character.isLetter(c)) {
                System.out.println(c + " is letter, uppercase: " + Character.isUpperCase(c));
            } else if (Character.isWhitespace(c)) {
                System.out.println("Found whitespace");
            }
        }

        // Case transformation
        char lower = 'a';
        char upper = Character.toUpperCase(lower);  // 'A'

        // Validating password requirements
        String password = "Pass123!";
        boolean hasDigit = password.chars().anyMatch(Character::isDigit);
        boolean hasLetter = password.chars().anyMatch(Character::isLetter);
        System.out.println("Valid password: " + (hasDigit && hasLetter));
    }
}

import java.math.BigDecimal;
import java.util.*;

public class NumberHierarchyDemo {
    // Method accepts any numeric type
    public static void printValue(Number num) {
        System.out.println("As int: " + num.intValue());
        System.out.println("As double: " + num.doubleValue());
    }

    public static void main(String[] args) {
        // All these types extend Number
        List<Number> metrics = new ArrayList<>();
        metrics.add(42);                          // Integer
        metrics.add(3.14);                        // Double
        metrics.add(100L);                        // Long
        metrics.add(new BigDecimal("999.99"));   // BigDecimal

        // Process different numeric types uniformly
        for (Number metric : metrics) {
            printValue(metric);
        }

        // Type-safe conversion
        Number revenue = 15000.50;
        int roundedRevenue = revenue.intValue();  // 15000
        double preciseRevenue = revenue.doubleValue();  // 15000.5
    }
}
